// @param float _HeartWidth = 1 [0.65 .. 1.25]
// @param float _NotchDepth = 1 [0.35 .. 1.8]
// @param float _TipLength = 1 [0.65 .. 1.3]
// @param float _Fullness = 1 [0.25 .. 1.8]

float2 HeartCurve(float2 a, float2 b, float2 c, float2 d, float t)
{
    float s = 1-t;
    return s*s*s*a + 3*s*s*t*b + 3*s*t*t*c + t*t*t*d;
}
void HeartEdge(float2 p, float2 a, float2 b, inout float distanceSq, inout float crossings)
{
    float2 e=b-a, v=p-a;
    float2 nearPoint=v-e*saturate(dot(v,e)/max(dot(e,e),0.000001));
    distanceSq=min(distanceSq,dot(nearPoint,nearPoint));
    if ((a.y>p.y)!=(b.y>p.y))
    {
        float x=a.x+(p.y-a.y)*(b.x-a.x)/(b.y-a.y);
        if(x>p.x)crossings+=1;
    }
}
void HeartArc(float2 p, float2 a, float2 b, float2 c, float2 d, inout float distanceSq, inout float crossings)
{
    float2 previous=a;
    [unroll] for(int i=1;i<=20;i++)
    {
        float2 next=HeartCurve(a,b,c,d,i/20.0);
        HeartEdge(p,previous,next,distanceSq,crossings);
        previous=next;
    }
}
float4 ApplyFX(float2 uv, float4 color)
{
    uv = LayerToLocal(uv);
    float2 p=float2(abs(uv.x*512-256),(1-uv.y)*512);
    float d=1000000, crossings=0;
    // Shape controls move the curve anchors, keeping symmetry and smooth joins.
    float width = _HeartWidth;
    float notch = 96.0 + 62.0 * _NotchDepth;
    float tip = 178.0 + 229.0 * _TipLength;
    HeartArc(p, float2(0,notch), float2(22*width,96+21*_NotchDepth),
        float2(62*width,96), float2(95*width,96), d,crossings);
    HeartArc(p, float2(95*width,96), float2(144*width,96),
        float2(180*width,131), float2(180*width,178), d,crossings);
    HeartArc(p, float2(180*width,178), float2(180*width,178+88*_TipLength),
        float2(79*width*_Fullness,178+164*_TipLength), float2(0,tip), d,crossings);
    float signedDistance=sqrt(d)*(fmod(crossings,2)>0.5?-1:1);
    float aa=max(fwidth(signedDistance), 0.0001);
    color.a*=saturate(0.5-signedDistance/aa);
    return color;
}
